mapper.update:
UPDATE task
task_title = #{taskTitle}, task_info = #{taskInfo}, task_operator_id = #{taskOperatorId}, task_status = #{taskStatus}, task_type = #{taskType}, task_update_time = #{taskUpdateTime}, task_finish_time = #{taskFinishTime}, task_remark = #{taskRemark},
WHERE id = #{id}

mapper.select:
SELECT t.*,
       u1.user_name AS owner_name,
       u2.user_name AS operator_name,
       tt.task_type_name
FROM task t
LEFT JOIN user u1 ON t.owner_id = u1.id
LEFT JOIN user u2 ON t.task_operator_id = u2.id
LEFT JOIN task_type tt ON t.task_type = tt.task_type_id


        AND t.owner_id = #{ownerId}


        AND t.task_operator_id = #{taskOperatorId}


        AND t.task_status = #{taskStatus}


        AND t.task_type = #{taskType}


ORDER BY t.id ASC
